//
// Test of mgc_flat_attn_pipeopt, generated by mgc from flat_attn_pipeopt.mgc: do not edit, re-run
// mgc/mgcc.py.

#include <stdint.h>

#include "mgc_flat_attn_pipeopt.h"
#include "test.h"

#include "tile.h"
#include "fsync.h"
#include "eventunit.h"

int main(void)
{
    uint32_t hartid = get_hartid();

    mgc_flat_attn_pipeopt(
        q_inp, k_inp, v_inp, o_out, SEQ_LENGTH, EMBED_SIZE, PROJ_SIZE, NUM_HEADS, QK_SCALE_FP16);

    /* once every tile has finished, each tile checks its share of the rows */
    fsync_init();
    eu_fsync_init(0);
    fsync_sync_global();
    eu_fsync_wait(WFE);

    uint32_t share  = (SEQ_LENGTH + NUM_HARTS - 1) / NUM_HARTS;
    uint32_t r_end  = (hartid + 1) * share < SEQ_LENGTH ? (hartid + 1) * share : SEQ_LENGTH;
    uint32_t errors = 0;
    uint16_t computed, expected, diff;
    for (uint32_t i = hartid * share; i < r_end; i++) {
        for (uint32_t j = 0; j < PROJ_SIZE; j++) {
            computed = *(volatile uint16_t *)(o_out + (i * PROJ_SIZE + j));
            expected = *(volatile uint16_t *)(o_gold + (i * PROJ_SIZE + j));
            diff     = (computed > expected) ? (computed - expected) : (expected - computed);
            if (diff > 0x0011) {
#if EVAL == 1
                printf("Error detected at coordinates[%d][%d]: o_out=%x o_gold=%x\n",
                       i,
                       j,
                       *(volatile uint16_t *)(o_out + (i * PROJ_SIZE + j)),
                       *(volatile uint16_t *)(o_gold + (i * PROJ_SIZE + j)));
#endif
                errors++;
            }
        }
    }
    printf("TILE %d: Number of errors: %d\n", hartid, errors);

    return errors;
}
